SELECT *
FROM flow_busi_info
WHERE process_key = #{processKey} AND `values` = #{values} AND `keys` = #{unKey}
AND NOT (
(
process_status = #{procInsFinish} AND bus_status = #{busiFinish})
OR process_status = #{procInsRefuse}
OR (process_status = #{procInsFinish} AND bus_status = #{busiErrorConfirmed}
)
)

SELECT *
FROM flow_busi_info
WHERE process_instance_id = #{processInstanceId}
AND NOT (
(
process_status = #{procInsFinish} AND bus_status = #{busiFinish})
OR process_status = #{procInsRefuse}
OR (process_status = #{procInsFinish} AND bus_status = #{busiErrorConfirmed}
)
)
